const DATA_FILE = process.env.DATA_FILE || path.join(process.cwd(), 'campaign-leads.json');
const RESERVATION_PHONE_DISPLAY = process.env.RESERVATION_PHONE_DISPLAY || '(02) 8524 4351';
const RESERVATION_PHONE_LINK = process.env.RESERVATION_PHONE_LINK || '+63285244351';
const attempts = new Map();
let writeQueue = Promise.resolve();

