let adminPage = String.raw`<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Campaign Records</title><style>body{font:15px system-ui;margin:0;background:#f4f6f1;color:#073f2c}.wrap{max-width:1100px;margin:auto;padding:30px}.login,.panel{background:white;padding:25px;border-radius:18px;box-shadow:0 10px 35px #073f2c18}.panel{display:none}.row{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}input,button{font:inherit;padding:11px 14px;border-radius:10px;border:1px solid #ccd6cf}button{background:#073f2c;color:white;font-weight:700;cursor:pointer}.export{background:#ffd94d;color:#073f2c}table{border-collapse:collapse;width:100%;font-size:13px}th,td{text-align:left;padding:10px;border-bottom:1px solid #e3e8e4;vertical-align:top}th{position:sticky;top:0;background:white}.table{overflow:auto;max-height:68vh}.badge{padding:4px 8px;border-radius:999px;background:#e6eddf;font-size:11px}.redeemed{background:#d9edcf}.muted{color:#6d776f}.stats{font-weight:700}h1{margin-top:0}@media(max-width:650px){.wrap{padding:15px}table{min-width:850px}}</style></head><body><div class="wrap"><div class="login" id="login"><h1>Campaign records</h1><p class="muted">Authorized campaign staff only.</p><div class="row"><input id="pin" type="password" placeholder="Admin PIN"><button id="enter">Open records</button></div><p id="error"></p></div><div class="panel" id="panel"><h1>Gift-pack registrations</h1><div class="row"><span class="stats" id="stats"></span><button class="export" id="export">Download CSV</button><button id="refresh">Refresh</button></div><div class="table"><table><thead><tr><th>Date</th><th>Claim code</th><th>Name</th><th>Mobile</th><th>Address</th><th>Marketing</th><th>Status</th><th>Action</th></tr></thead><tbody id="rows"></tbody></table></div></div></div><script>let pin='';async function load(){const r=await fetch('/api/leads',{headers:{'x-admin-pin':pin}});const data=await r.json();if(!r.ok)throw new Error(data.error||'Unable to open records.');document.querySelector('#login').style.display='none';document.querySelector('#panel').style.display='block';document.querySelector('#stats').textContent=data.leads.length+' registered • '+data.leads.filter(x=>x.redeemedAt).length+' redeemed';const rows=document.querySelector('#rows');rows.innerHTML='';data.leads.forEach(x=>{const tr=document.createElement('tr');[new Date(x.createdAt).toLocaleString(),x.claimCode,x.name,x.phone,x.address,x.marketing?'Yes':'No'].forEach(value=>{const td=document.createElement('td');td.textContent=String(value??'');tr.appendChild(td)});const status=document.createElement('td');status.innerHTML=x.redeemedAt?'<span class="badge redeemed">Redeemed</span>':'<span class="badge">Pending</span>';tr.appendChild(status);const action=document.createElement('td');if(!x.redeemedAt){const b=document.createElement('button');b.textContent='Mark redeemed';b.onclick=async()=>{if(!confirm('Mark '+x.claimCode+' as redeemed?'))return;await fetch('/api/redeem',{method:'POST',headers:{'Content-Type':'application/json','x-admin-pin':pin},body:JSON.stringify({claimCode:x.claimCode})});load()};action.appendChild(b)}tr.appendChild(action);rows.appendChild(tr)})}document.querySelector('#enter').onclick=()=>{pin=document.querySelector('#pin').value;load().catch(e=>document.querySelector('#error').textContent=e.message)};document.querySelector('#refresh').onclick=load;document.querySelector('#export').onclick=async()=>{const r=await fetch('/api/export',{headers:{'x-admin-pin':pin}});if(!r.ok)return alert('Export failed.');const blob=await r.blob(),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='puregold-monumento-campaign.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};document.querySelector('#pin').addEventListener('keydown',e=>{if(e.key==='Enter')document.querySelector('#enter').click()});</script></body></html>`;

adminPage = adminPage
  .replace('</style>', `.searchbar{display:grid;grid-template-columns:1fr auto auto;gap:10px;margin:18px 0}.searchbar input{min-width:220px}.scan{background:#ffd94d;color:#073f2c}.filter-count{align-self:center;color:#6d776f;font-size:12px}.scan-modal{display:none;position:fixed;inset:0;background:#032f21e8;z-index:20;padding:20px;place-items:center}.scan-modal.open{display:grid}.scan-card{width:min(500px,100%);background:white;border-radius:20px;padding:20px}.scan-card video{display:block;width:100%;max-height:60vh;background:#111;border-radius:14px;object-fit:cover}.scan-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.scan-head h2{margin:0}.scan-head button{background:#e9eee9;color:#073f2c}.scan-status{color:#6d776f;font-size:13px}@media(max-width:650px){.searchbar{grid-template-columns:1fr 1fr}.searchbar input{grid-column:1/-1}}</style>`)
  .replace('<div class="table">', `<div class="searchbar"><input id="recordSearch" type="search" placeholder="Search claim code, name, phone or address"><button class="scan" id="scanQr">▣ Scan QR</button><span class="filter-count" id="filterCount"></span></div><div class="table">`)
  .replace('</body>', `<div class="scan-modal" id="scanModal"><div class="scan-card"><div class="scan-head"><h2>Scan claim QR</h2><button id="closeScan">Close</button></div><video id="scanVideo" playsinline muted></video><p class="scan-status" id="scanStatus">Point the camera at the customer's QR code.</p></div></div><script>
    const recordSearch=document.querySelector('#recordSearch'),filterCount=document.querySelector('#filterCount'),recordsBody=document.querySelector('#rows');let scanStream=null,scanFrame=null;
    function filterRecords(){const query=recordSearch.value.trim().toLowerCase();let shown=0;recordsBody.querySelectorAll('tr').forEach(row=>{const visible=!query||row.textContent.toLowerCase().includes(query);row.hidden=!visible;if(visible)shown++});filterCount.textContent=shown+' matching record'+(shown===1?'':'s');}
    recordSearch.addEventListener('input',filterRecords);new MutationObserver(filterRecords).observe(recordsBody,{childList:true});
    function stopScanner(){if(scanFrame)cancelAnimationFrame(scanFrame);scanFrame=null;if(scanStream)scanStream.getTracks().forEach(track=>track.stop());scanStream=null;document.querySelector('#scanModal').classList.remove('open');}
    function useScannedValue(value){let code=String(value||'').trim();const match=code.match(/PGM-[A-F0-9]{8}/i);if(match)code=match[0].toUpperCase();recordSearch.value=code;filterRecords();stopScanner();const visible=[...recordsBody.querySelectorAll('tr')].find(row=>!row.hidden);if(visible){visible.scrollIntoView({behavior:'smooth',block:'center'});visible.style.background='#fff6c9';setTimeout(()=>visible.style.background='',2500)}}
    async function startScanner(){const modal=document.querySelector('#scanModal'),status=document.querySelector('#scanStatus'),video=document.querySelector('#scanVideo');modal.classList.add('open');if(!navigator.mediaDevices?.getUserMedia||!window.BarcodeDetector){status.textContent='Live QR scanning needs a recent Chrome or Android browser. Use the search box to enter the backup claim code.';return}try{scanStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}}});video.srcObject=scanStream;await video.play();const detector=new BarcodeDetector({formats:['qr_code']});async function detect(){try{const codes=await detector.detect(video);if(codes.length)return useScannedValue(codes[0].rawValue)}catch(error){}scanFrame=requestAnimationFrame(detect)}detect()}catch(error){status.textContent='Camera access was not available. Allow camera permission or use the search box.'}}
    document.querySelector('#scanQr').addEventListener('click',startScanner);document.querySelector('#closeScan').addEventListener('click',stopScanner);document.querySelector('#scanModal').addEventListener('click',event=>{if(event.target.id==='scanModal')stopScanner()});
  </script></body>`);

async function handler(req, res) {
  const url = new URL(req.url, 'http://localhost');
  try {
    if (url.pathname === '/health') return json(res, 200, { ok: true });
    if (url.pathname === '/api/qr' && req.method === 'GET') {
      const code = clean(url.searchParams.get('code'), 20).toUpperCase();
      if (!/^PGM-[A-F0-9]{8}$/.test(code)) return json(res, 400, { error: 'Invalid claim code.' });
      const qrModule = await import('qrcode'), QRCode = qrModule.default || qrModule;
      const image = await QRCode.toBuffer(code, { type: 'png', width: 260, margin: 2, color: { dark: '#073f2c', light: '#ffffff' } });
      res.writeHead(200, { 'Content-Type': 'image/png', 'Cache-Control': 'public, max-age=31536000, immutable', 'X-Content-Type-Options': 'nosniff' });
      return res.end(image);
    }
    if (url.pathname === '/api/register' && req.method === 'POST') {
      if (rateLimited(req)) return json(res, 429, { error: 'Too many attempts. Please try again later.' });
      const input = await bodyFrom(req), name = clean(input.name, 100), address = clean(input.address, 240), phone = normalizePhone(input.phone);
      if (name.length < 3) return json(res, 400, { error: 'Please enter your complete name.' });
      if (address.length < 10) return json(res, 400, { error: 'Please enter your complete address.' });
      if (!/^09\d{9}$/.test(phone)) return json(res, 400, { error: 'Enter a valid Philippine mobile number beginning with 09.' });
      if (input.consent !== true) return json(res, 400, { error: 'Consent is required to register for this campaign.' });
      const leads = await readLeads(), existing = leads.find(item => item.phone === phone);
      if (existing) return json(res, 200, { ok: true, claimCode: existing.claimCode, existing: true });
      const lead = { id: crypto.randomUUID(), claimCode: claimCode(), name, phone, address, marketing: input.marketing === true, createdAt: new Date().toISOString(), redeemedAt: null };
      leads.push(lead); await saveLeads(leads); return json(res, 201, { ok: true, claimCode: lead.claimCode });
    }
    if (url.pathname === '/api/leads') {
      if (!ADMIN_PIN) return json(res, 503, { error: 'ADMIN_PIN is not configured on the server.' });
      if (!authorized(req, url)) return json(res, 401, { error: 'Unauthorized' });
      const leads = await readLeads();
      return json(res, 200, { leads: leads.sort((a,b) => b.createdAt.localeCompare(a.createdAt)) });
    }
    if (url.pathname === '/api/redeem' && req.method === 'POST') {
      if (!ADMIN_PIN) return json(res, 503, { error: 'ADMIN_PIN is not configured on the server.' });
      if (!authorized(req, url)) return json(res, 401, { error: 'Unauthorized' });
      const input = await bodyFrom(req), code = clean(input.claimCode, 20).toUpperCase(), leads = await readLeads(), lead = leads.find(item => item.claimCode === code);
      if (!lead) return json(res, 404, { error: 'Claim code not found.' });
      if (!lead.redeemedAt) { lead.redeemedAt = new Date().toISOString(); await saveLeads(leads); }
      return json(res, 200, { ok: true, redeemedAt: lead.redeemedAt });
    }
    if (url.pathname === '/api/export') {
      if (!ADMIN_PIN) return json(res, 503, { error: 'ADMIN_PIN is not configured on the server.' });
      if (!authorized(req, url)) return json(res, 401, { error: 'Unauthorized' });
      const quote = value => { const safe = String(value ?? '').replace(/^([=+\-@])/, "'$1"); return '"' + safe.replace(/"/g, '""') + '"'; };
      const leads = await readLeads();
      const rows = [['Created','Claim Code','Name','Phone','Address','Marketing Opt-in','Redeemed At'], ...leads.map(x => [x.createdAt,x.claimCode,x.name,x.phone,x.address,x.marketing?'Yes':'No',x.redeemedAt||''])];
      res.writeHead(200, { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': 'attachment; filename="puregold-monumento-campaign.csv"', 'Cache-Control': 'no-store' });
      return res.end('\uFEFF' + rows.map(row => row.map(quote).join(',')).join('\r\n'));
    }
    if (url.pathname === '/admin') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store' }); return res.end(adminPage); }
    if (url.pathname === '/christmas-baskets') { res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300', 'X-Content-Type-Options': 'nosniff' }); return res.end(christmasPage); }
    res.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'public, max-age=300', 'X-Content-Type-Options': 'nosniff', 'Referrer-Policy': 'strict-origin-when-cross-origin' });
    res.end(page);
  } catch (error) { console.error(error); const storageError = String(error.message || error).includes('storage_not_configured'); json(res, storageError ? 503 : 500, { error: storageError ? 'Registration storage is not configured yet.' : 'Something went wrong. Please try again.' }); }
}

module.exports = handler;

if (require.main === module) {
  http.createServer(handler).listen(PORT, '0.0.0.0', () => console.log('Puregold Monumento campaign is ready on port ' + PORT));
}
